import html
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
r=json.loads((ROOT/'public/data/release.json').read_text())
crossing=r['refined_crossings'][0]
def reading(site,body,t,rows=None):
    row=next(row for row in (rows or r['samples']) if row['site_id']==site and row['body_id']==body and row['timestamp_utc']==t)
    return f"{row['azimuth_deg']:.3f}°",f"{row['elevation_deg']:+.3f}°"
initial=r['timestamps'][0]
cells=''.join(f"<tr><td>{site['name']}</td><td>{'Sun' if body==10 else 'Earth'}</td><td>{reading(site['id'],body,initial)[0]}</td><td>{reading(site['id'],body,initial)[1]}</td></tr>" for site in r['sites'] for body in (10,399))
before=reading('im1',10,crossing['start_utc'],r['refined_samples'])[1]
after=reading('im1',10,crossing['end_utc'],r['refined_samples'])[1]
slides=[
    '<p class="eyebrow">INDEPENDENT LUNAR VISIBILITY EXPLORER</p><h1>RIMWAKE</h1><h2>Two places.<br><em>One lunar sky.</em></h2><p class="lead">See how location changes the geometric view of the Sun and Earth.<br>Inspect every reading’s source.</p><p class="small">Local P0 demonstrator · NASA/JPL data · Provisional science · 14 November 2026</p>',
    '<p class="eyebrow">01 / THE OBSERVERS</p><h2>Grounded coordinates.<br><em>Explicit assumptions.</em></h2><div class="columns"><div><h3>Odysseus · IM-1</h3><p class="number">80.13° S<br>1.44° E</p></div><div><h3>Athena · IM-2</h3><p class="number">84.7906° S<br>29.1957° E</p></div></div><p>Approximate historical landing positions from NASA NSSDCA. Each is used as a <strong>hypothetical observer at 0 km above the Horizons lunar reference ellipsoid</strong>, not the lander’s actual instrument height. Exact frame reconciliation remains open.</p>',
    f'<p class="eyebrow">02 / ONE SHARED INSTANT</p><h2>Different views.<br><em>The same UTC.</em></h2><p>14 November 2026 · 00:00 UTC · apparent airless centre-of-disc positions</p><table><thead><tr><th>Observer</th><th>Body</th><th>Azimuth</th><th>Elevation</th></tr></thead><tbody>{cells}</tbody></table><p class="small">North 0°, east 90°, clockwise. Negative elevation means below the tangent plane. Terrain is excluded.</p>',
    f'<p class="eyebrow">03 / A REAL CROSSING BRACKET</p><h2>A threshold crossed.<br><em>Not an invented timestamp.</em></h2><div class="columns"><div><h3>16 NOV · 03:30 UTC</h3><p class="number amber">{before}</p><p>Sun centre below tangent plane</p></div><div><h3>16 NOV · 03:40 UTC</h3><p class="number amber">{after}</p><p>Sun centre above tangent plane</p></div></div><p>At the IM-1 coordinate observer, the crossing falls between these sampled times. A 35-day hourly discovery scan found eight coarse brackets across the two sites. The first crossing in processing order was refined to ten-minute samples.</p><p class="small">This illustrates one selected event, not typical conditions or guaranteed sunlight at a real spacecraft.</p>',
    '<p class="eyebrow">04 / EVIDENCE YOU CAN INSPECT</p><h2>From source<br><em>to sky plot.</em></h2><div class="chain"><span>NASA coordinates<br>+ JPL queries</span><b>→</b><span>Raw responses<br>+ SHA-256</span><b>→</b><span>Validated schema<br>+ shared UTC</span></div><p>3,364 coarse readings + 28 refined readings. Full query lineage and a downloadable evidence archive. Fail-closed loading, signed angles, sampled timelines and transparent unknown states.</p><p>Separate initial Sun requests match at both sites (0° reported difference). That confirms request/parse consistency; <strong>independent ephemeris validation has not been run</strong>.</p>',
    '<p class="eyebrow">05 / KNOW THE LIMITS</p><h2>The horizon<br><em>is a beginning.</em></h2><p>Geometric tangent plane only. Local terrain, finite discs, eclipses, power generation and RF link performance are excluded. Above-horizon geometry does not guarantee usable light or communication.</p><p class="small">Sources: <a href="https://nssdc.gsfc.nasa.gov/planetary/lunar/lunar_artifact_impacts.html">NASA NSSDCA lunar artifact catalog</a> · <a href="https://ssd-api.jpl.nasa.gov/doc/horizons.html">JPL Horizons API</a> · <a href="https://ssd.jpl.nasa.gov/horizons/manual.html">Horizons manual</a>. Full ledger: docs/source-ledger.md.</p><p class="small">React, Vite, TypeScript, Python. Codex assisted implementation, data ingestion, tests and copy. Original vectors; no generated imagery. Independent project; no NASA endorsement.</p><p class="small">Local only: no public site or submitted project yet. Challenge Resources eligibility and portal rules remain unverified. Terrain expansion requires owner approval.</p>'
]
css='''@font-face{font-family:DM;src:url('../node_modules/@fontsource/dm-sans/files/dm-sans-latin-400-normal.woff2')}*{box-sizing:border-box}body{margin:0;background:#e9e9df;color:#202b24;font-family:DM,Arial,sans-serif}.slide{position:relative;width:1280px;min-height:720px;height:720px;padding:64px 80px;break-after:page;overflow:hidden}.slide:nth-child(even){background:#101a15;color:#e2e6d7}.slide:last-child{break-after:auto}.eyebrow{font:13px monospace;letter-spacing:2px;margin:0 0 38px}h1{font-size:38px;letter-spacing:8px;font-weight:500;margin:0 0 25px}h2{font-weight:400;font-size:66px;letter-spacing:-3px;line-height:1.04;margin:0 0 30px}em{font-style:normal;color:#71816a}.slide:nth-child(even) em{color:#bdcda5}p{font-size:23px;line-height:1.55;max-width:1060px;margin:20px 0}.lead{font-size:26px}.small{font-size:16px;line-height:1.7}.columns{display:grid;grid-template-columns:1fr 1fr;gap:50px}.columns h3{font:15px monospace;letter-spacing:1px}.number{font:46px monospace;line-height:1.5;margin:10px 0 20px}.amber{color:#e6bd76}.chain{display:flex;align-items:center;gap:30px;padding:26px 0;font:22px/1.5 monospace}.chain span{border-block:1px solid #6d8059;padding:20px}.chain b{font-weight:400;color:#71816a}table{border-collapse:collapse;width:100%;font:21px monospace;margin:25px 0}th,td{text-align:left;border-bottom:1px solid #aab49b;padding:15px 0}th{font-size:14px;font-weight:400}footer{position:absolute;bottom:25px;left:80px;right:80px;display:flex;justify-content:space-between;font:11px monospace;letter-spacing:1px}a{color:inherit;text-underline-offset:3px}@page{size:1280px 720px;margin:0}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
slides[2]=slides[2].replace('Different views.<br><em>The same UTC.</em>','Different views. <em>The same UTC.</em>')
slides[3]=slides[3].replace('A threshold crossed.<br><em>Not an invented timestamp.</em>','A real <em>threshold crossing.</em>')
css+='.slide:nth-child(3) h2,.slide:nth-child(4) h2{font-size:56px}.slide:nth-child(3) .eyebrow,.slide:nth-child(4) .eyebrow{margin-bottom:25px}.slide:nth-child(3) p,.slide:nth-child(4) p{font-size:20px;margin:15px 0}.slide:nth-child(3) .small,.slide:nth-child(4) .small{font-size:16px}.slide:nth-child(4) .number{font-size:46px}.slide:nth-child(3) th,.slide:nth-child(3) td{padding:13px 0}'
document='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>RIMWAKE · Six-slide demo</title><style>'+css+'</style></head><body>'+''.join(f'<section class="slide">{slide}<footer><span>RIMWAKE / LOCAL P0</span><span>{i+1:02d} / 06</span></footer></section>' for i,slide in enumerate(slides))+'</body></html>'
(ROOT/'docs/demo-slides.html').write_text(document,encoding='utf8')
print('Created six evidence-bounded demo slides from released values.')
